entries[188252] = { ["name"] = "Chains of Domination", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 [Agility or Strength]\nUse: Drive a spike into your target, dealing 7116 Physical damage and creating a chain link between you for 20 sec. While the chain persists, 25% of all damage dealt to the target is stored within it, up to a maximum of 3019 .\n\nMoving away from your target will rip the chain out, dealing the stored amount as Shadow damage to all enemies within 8 yds of them. (3 Min Cooldown)\nSell Price:" }
entries[188253] = { ["name"] = "Scars of Fraternal Strife", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Affix a Domination Rune to yourself, gaining power at a price.\nUse: Add another. (30 Sec Cooldown)\nSell Price:" }
entries[188254] = { ["name"] = "Grim Eclipse", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Intellect\nUse: Manifest a Quasar which orbits your target, blasting it with 3622 Cosmic damage over 7 sec.\n\nAfter 7 sec, the Quasar stabilizes, creating an Event Horizon for 10 sec which grants you 319 Haste while within its perimeter. (2 Min Cooldown)\nSell Price:" }
entries[188255] = { ["name"] = "Heart of the Swarm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Strength\nUse: Invoke the swarm, losing the ability to cast or attack but transforming into a swarm of hungering locusts, gaining 71 Speed and 354 Leech, and dealing ( 3439 * 3) Shadow damage split between all nearby enemies over 3 sec.\n\nDamage is increased for each enemy struck, up to 5 enemies. (3 Min Cooldown)\nSell Price:" }
