entries[188261] = { ["name"] = "Intrusive Thoughtcage", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 [Agility or Strength]\nUse: Establish a link deep within your target's mind, increasing your dodge rating by 222 , and draining [source value] health over 6 sec.\n\nIf the link is still intact when this effect ends, their mind shatters, dealing 1091 Shadow damage to enemies within 8 yds of them and Horrifying them for 3 sec. (3 Min Cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[188262] = { ["name"] = "The Lion's Roar", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nClasses: Paladin , Priest , Shaman , Monk , Druid , Evoker\nUse: Channel the Light for 3 sec, creating a zone of protection around you, absorbing 30% of all damage taken by allies within, up to a total of 27443 .\n\nYour critical heals have a chance to reduce the cooldown by 6 sec.\n\nValid only for healer specializations. (10 Min Cooldown)\nSell Price:" }
entries[188263] = { ["name"] = "Reclaimer's Intensity Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nEquip: Whenever a nearby Automa dies, you exude Ephemera, healing up to 5 nearby allies for ( 45 * 30) over 30 sec.\nUse: Call forth an Automa Medic which restores ( 14 * 10) mana to you over 10 sec before expiring. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[188264] = { ["name"] = "Earthbreaker's Impact", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nUse: Cause the ground to quake beneath your feet, dealing 4445 Nature damage split between all nearby enemies over 12 sec. Damage increased per target hit.\n\nWhile quaking, you can sense nearby tectonic weak points. Moving over a weak point will deal an additional 635 Nature damage to all nearby enemies. (3 Min Cooldown)\nSell Price:" }
entries[188265] = { ["name"] = "Cache of Acquired Treasures", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Agility\nEquip: Periodically rummage through the cache, finding a new stolen weapon.\nUse: Grab the weapon from the cache, gaining its benefit. (3 Min Cooldown)\nSell Price:" }
entries[188266] = { ["name"] = "Pulsating Riftshard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nUse: Places a Rift Portal in front of you that charges for 1.5 sec before unleashing a blast of [ 1739 * (1 + Versatility)] Cosmic damage split between enemies in a line. The portal plunders reality itself, granting you a shield for 20 sec which absorbs [ 4016 * (1 + Versatility)] damage.\n\nDamage and absorption are increased for each enemy struck, up to 5 enemies. (1 Min Cooldown)\nSell Price:" }
entries[188267] = { ["name"] = "Bells of the Endless Feast", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nEquip: Your damaging abilities have a high chance to smell out the scent of delicious soul energy, stacking up to 100 times. At full stacks, a swarm of devourers burst forth, chomping your target for 5733 Physical damage.\n\nEffects that cause your target to move generate bonus stacks.\nSell Price:" }
entries[188268] = { ["name"] = "Architect's Ingenuity Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nEquip: Whenever a nearby Automa dies, your cooldowns recover 5% more quickly for 30 sec.\nUse: Call forth an Attendant Automa who channels ( 53 * 8) Cosmic damage onto your target over 8 sec, after which it expires. (1 Min, 30 Sec Cooldown)\nSell Price:" }
